files.manifest.json:
{
  "name": "convert_currency_to_czk_cnb",
  "kind": "workflow",
  "description": "Converts an amount in any currency to CZK using the current official \u010cNB daily exchange rate.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"amount\":{\"type\":\"number\"},\"currency\":{\"type\":\"string\"}},\"required\":[\"amount\",\"currency\"]}",
    "out": "output of s1"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "convert_to_czk_cnb_rate",
      "foreach": null,
      "inputs": [
        {
          "param": "amount",
          "source": "$input.amount"
        },
        {
          "param": "currency",
          "source": "$input.currency"
        }
      ]
    }
  ],
  "output_step": "s1",
  "permissions": {
    "net": [
      "www.cnb.cz"
    ],
    "llm": false
  },
  "budget": {
    "max_tokens_per_run": 0
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "convert_to_czk_cnb_rate@v1"
    ]
  },
  "example_input": "{\"amount\":250,\"currency\":\"EUR\"}",
  "purpose": "a bot that converts an amount in any currency to CZK at today's official \u010cNB exchange rate",
  "version": 1,
  "headline": "{amount} {currency} is {czk} CZK at the \u010cNB rate of {rate_date} ({rate} CZK per {unit_amount} {currency}).",
  "examples": [
    "How much is 250 EUR in Czech crowns?",
    "Convert 100 USD to CZK",
    "What is 5000 JPY worth in CZK today?"
  ],
  "voice": "gremlin",
  "manual_minutes": 3.0,
  "manual_basis": "Look up current \u010cNB exchange rate for the currency, then multiply the amount by the rate to convert to CZK."
}

